/* Baseline implementation: heap-layout complete trees, uint8 thresholds,
 * int8 leaves, int32 accumulator. One sample = RAPT_K x RAPT_DEPTH compares. */
uint8 roundabout_priority_tree_predict(uint16 CH1, uint16 CH2, uint16 CH3,
                                       uint16 CH4, uint16 TOF)
{
    uint8 x[10];
    int32 acc = 0;
    uint8 lv;
    int t, idx;
    {
        uint8 c1 = CH1 > 255u ? 255u : (uint8)CH1;
        uint8 c2 = CH2 > 255u ? 255u : (uint8)CH2;
        uint8 c3 = CH3 > 255u ? 255u : (uint8)CH3;
        uint8 c4 = CH4 > 255u ? 255u : (uint8)CH4;
        uint32 q = (uint32)TOF / 32u, r = (uint32)TOF % 32u;
        uint8 tf;
        int v;
        if (r > 16u) q += 1u;
        else if (r == 16u) q += (q & 1u);          /* round half to even, matches training */
        tf = q > 255u ? 255u : (uint8)q;
        x[0] = c1; x[1] = c2; x[2] = c3; x[3] = c4; x[4] = tf;
        v = ((int)c4 - (int)c1 + 268) / 2;  x[5] = (uint8)(v > 255 ? 255 : v);
        v = ((int)c2 - (int)c3 + 148) / 2;  x[6] = (uint8)(v > 255 ? 255 : v);
        v = (int)c2 + (int)c3;              x[7] = (uint8)(v > 255 ? 255 : v);
        v = ((int)c1 + (int)c4) / 2;        x[8] = (uint8)(v > 255 ? 255 : v);
        v = c1 > c4 ? (int)c1 - (int)c4 : (int)c4 - (int)c1;
                                            x[9] = (uint8)(v > 255 ? 255 : v);
    }
    for (t = 0; t < RAPT_K; ++t) {
        idx = 0;
        for (lv = 0; lv < RAPT_DEPTH; ++lv)
            idx = idx * 2 + 1 + (x[rapt_feat[t][idx]] > rapt_thr[t][idx]);
        acc += rapt_leaf[t][idx - RAPT_NODES];
    }
    return (acc >= RAPT_TAU) ? (uint8)1 : (uint8)0;
}

